      await paymentService.processPayment(p2.id);

      const stats = await paymentService.getPaymentStats();
      expect(stats.totalPayments).toBe(2);
      expect(stats.totalRevenue).toBe(3000);
      expect(stats.averageAmount).toBe(1500);
    });
  });
